int count = 0;
auto begin = tree.all_intersected_primitives(b);
auto end = tree.all_intersected_primitives_end(b);
for (auto it = begin; it != end; ++it) {
    const auto* tri = *it;
    const auto& p0 = tri->vertex(0);
    const auto& p1 = tri->vertex(1);
    const auto& p2 = tri->vertex(2);
    bool inside =
        b.xmin() <= p0.x() && p0.x() <= b.xmax() &&
        b.ymin() <= p0.y() && p0.y() <= b.ymax() &&
        b.zmin() <= p0.z() && p0.z() <= b.zmax() &&
        b.xmin() <= p1.x() && p1.x() <= b.xmax() &&
        b.ymin() <= p1.y() && p1.y() <= b.ymax() &&
        b.zmin() <= p1.z() && p1.z() <= b.zmax() &&
        b.xmin() <= p2.x() && p2.x() <= b.xmax() &&
        b.ymin() <= p2.y() && p2.y() <= b.ymax() &&
        b.zmin() <= p2.z() && p2.z() <= b.zmax();
    if (inside) ++count;
}
return count;

